SELECT @@innodb_deadlock_detect,@@innodb_lock_wait_timeout;
-- Require deadlock_detect=ON; complete gates before timeout. Do not change production settings.

-- A1 in connection A:
START TRANSACTION;
UPDATE lock_probe SET n=n+1 WHERE id=1;
-- B1 in separate connection B, only after A1 returned successfully:
-- START TRANSACTION;
-- UPDATE lock_probe SET n=n+1 WHERE id=2;
-- GATE: BOTH first updates succeeded, neither transaction committed/rolled back.

-- A2: submit in A. It waits, so keep B/O terminals usable:
UPDATE lock_probe SET n=n+1 WHERE id=2;
-- O: verify an A->B wait exists in performance_schema.data_lock_waits.
-- B2: while A2 remains blocked:
-- UPDATE lock_probe SET n=n+1 WHERE id=1;
-- Expect an InnoDB victim error 1213/SQLSTATE 40001, not a fixed A/B victim.
-- In the victim connection: ROLLBACK;
-- In the successful survivor connection: COMMIT;
-- Then SELECT * FROM lock_probe ORDER BY id; expect n=1 for BOTH rows.
-- If any gate fails or 1205/transport error occurs: ROLLBACK both, report aborted run.
-- Once both transactions ended, reset only this disposable fixture:
-- UPDATE lock_probe SET n=0;

-- A1，独立连接 A
START TRANSACTION;
UPDATE s3_lock SET note='A' WHERE id=1;
-- B1，独立连接 B，在 A1 返回后执行：
-- START TRANSACTION;
-- UPDATE s3_lock SET note='B' WHERE id=2;
-- 闸门：两个首锁都成功，均未结束事务。
-- A2，由 A 发送并等待：
UPDATE s3_lock SET note='A' WHERE id=2;
-- 观察连接确认 A 等 B 的 s3_lock 等待边后，B2 执行：
-- UPDATE s3_lock SET note='B' WHERE id=1;

import java.sql.*;
import java.util.*;
import java.util.concurrent.*;

/** Controlled MySQL experiment. Requires fresh lock_probe rows 1 and 2, n=0. */
public final class DeadlockDemo {
    private DeadlockDemo(){}
    public record Result(int commits,int deadlocks,int sum){}
    public static Result run(Db.Source source) throws Exception {
        try(Connection c=source.open();Statement s=c.createStatement();ResultSet r=s.executeQuery(
                "SELECT @@innodb_deadlock_detect,@@innodb_lock_wait_timeout")) {
            r.next();if(!r.getBoolean(1) || r.getLong(2)<10)
                throw new IllegalStateException("requires detection ON and lock timeout >=10; no setting changed");
        }
        CountDownLatch firstLocks=new CountDownLatch(2);
        ExecutorService pool=Executors.newFixedThreadPool(2);
        List<Connection> live=Collections.synchronizedList(new ArrayList<>());
        List<Future<String>> jobs=new ArrayList<>();
        Throwable primary = null;
        try{
            for(int first=1;first<=2;first++){
                final int id=first;
                jobs.add(pool.submit(()->{
                    try(Connection c=source.open()){
                        live.add(c);c.setAutoCommit(false);
                        try(PreparedStatement p=Db.prepare(c,"UPDATE lock_probe SET n=n+1 WHERE id=?")){
                            p.setInt(1,id);if(p.executeUpdate()!=1)throw new SQLException("first row missing");
                            firstLocks.countDown();
                            if(!firstLocks.await(2,TimeUnit.SECONDS))throw new SQLException("gate failed; no deadlock established");
                            p.setInt(1,3-id);if(p.executeUpdate()!=1)throw new SQLException("second row missing");
                            c.commit();return "COMMIT";
                        }catch(SQLException e){
                            Db.rollback(c,e);
                            if(e.getErrorCode()==1213 && "40001".equals(e.getSQLState()))return "DEADLOCK";
                            throw e;
                        }catch(InterruptedException e){
                            Db.rollback(c,e);Thread.currentThread().interrupt();throw e;
                        }finally{live.remove(c);}
                    }
                }));
            }
            int commits=0,deadlocks=0;long deadline=System.nanoTime()+12_000_000_000L;
            for(Future<String> f:jobs){
                String result=f.get(Math.max(1,deadline-System.nanoTime()),TimeUnit.NANOSECONDS);
                if(result.equals("COMMIT"))commits++;else deadlocks++;
            }
            try(Connection c=source.open();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT SUM(n) FROM lock_probe")){
                r.next();return new Result(commits,deadlocks,r.getInt(1));
            }
        } catch (Exception | Error failure) { primary = failure; throw failure; }
        finally {
            Throwable failure = primary;
            for (Future<String> future : jobs) {
                try { future.cancel(true); }
                catch (RuntimeException | Error cleanup) { failure = keepFailure(failure, cleanup); }
            }
            // Only connections created by this disposable experiment are aborted.
            synchronized (live) {
                for (Connection connection : live) {
                    try { connection.abort(Runnable::run); }
                    catch (SQLException | RuntimeException | Error cleanup) { failure = keepFailure(failure, cleanup); }
                }
            }
            try { pool.shutdownNow(); }
            catch (RuntimeException | Error cleanup) { failure = keepFailure(failure, cleanup); }
            try {
                if (!pool.awaitTermination(8,TimeUnit.SECONDS)) throw new IllegalStateException("workers did not stop");
            } catch (InterruptedException | RuntimeException | Error cleanup) {
                if (cleanup instanceof InterruptedException) Thread.currentThread().interrupt();
                failure = keepFailure(failure, cleanup);
            }
            if (primary == null && failure != null) {
                if (failure instanceof Exception exception) throw exception;
                throw (Error) failure;
            }
        }
    }
    private static Throwable keepFailure(Throwable first, Throwable next) {
        if (first == null) return next;
        if (first != next) {
            for (Throwable saved : first.getSuppressed()) if (saved == next) return first;
            first.addSuppressed(next);
        }
        return first;
    }
}

import java.lang.reflect.Proxy;
import java.sql.*;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

/** Tests only Java validation/transaction orchestration using fake JDBC connections. */
public final class LocalChecks {
    private static int checks;
    private static void check(boolean value) { checks++;if(!value)throw new AssertionError("check "+checks); }
    private static final class FakeSource implements Db.Source {
        int opens,commits,rollbacks,closes;
        boolean failCommit,failRollback;
        @Override public Connection open() {
            opens++;
            return (Connection)Proxy.newProxyInstance(LocalChecks.class.getClassLoader(),new Class<?>[]{Connection.class},
                (proxy,method,args)->{
                    switch(method.getName()){
                        case "setAutoCommit", "setTransactionIsolation": return null;
                        case "commit": commits++;if(failCommit)throw new SQLException("lost acknowledgement","08006",0);return null;
                        case "rollback": rollbacks++;if(failRollback)throw new SQLException("rollback failed");return null;
                        case "close": closes++;return null;
                        case "isClosed": return false;
                        case "toString": return "fake JDBC only";
                        default: throw new UnsupportedOperationException(method.getName());
                    }
                });
        }
    }
    public static void main(String[] args) throws Exception {
        check(Db.duplicate(new SQLException("duplicate","23000",1062)));
        check(!Db.duplicate(new SQLException("foreign key","23000",1452)));
        check(!Db.duplicate(new SQLException("H2 duplicate","23505",23505)));
        check(Db.retryable(new SQLException("deadlock","40001",1213)));
        check(!Db.retryable(new SQLException("transport","08006",0)));
        for(String bad:new String[]{"", "a b", "中文", "x".repeat(101)}) {
            try {Db.key(bad);throw new AssertionError();}catch(IllegalArgumentException expected){checks++;}
        }
        Db.key("valid-01:_A");checks++;
        check(BucketReservations.normalize(List.of(new BucketReservations.Request("a",2),
                new BucketReservations.Request("a",2))).size()==1);
        try {BucketReservations.normalize(List.of(new BucketReservations.Request("a",2),
                new BucketReservations.Request("a",3)));throw new AssertionError();}
        catch(IllegalArgumentException expected){checks++;}
        TaskCas.validate("NEW",0,"RUNNING");checks++;
        for(String bad:new String[]{"NEW", "SUCCEEDED"}){
            try{TaskCas.validate(bad,0,"FAILED");throw new AssertionError();}
            catch(IllegalArgumentException expected){checks++;}
        }
        try{TaskCas.validate("NEW",Long.MAX_VALUE,"RUNNING");throw new AssertionError();}
        catch(IllegalArgumentException expected){checks++;}
        FakeSource success=new FakeSource();check(Db.transaction(success,c->42)==42);
        check(success.opens==1 && success.commits==1 && success.closes==1);
        for(int code:new int[]{1213,1205}){
            FakeSource retry=new FakeSource();AtomicInteger runs=new AtomicInteger();
            check(Db.transaction(retry,c->{if(runs.incrementAndGet()==1)throw new SQLException("retry","40001",code);return 7;})==7);
            check(retry.opens==2 && retry.rollbacks==1 && retry.commits==1 && retry.closes==2);
        }
        FakeSource unknown=new FakeSource();unknown.failCommit=true;
        try{Db.transaction(unknown,c->1);throw new AssertionError();}catch(Db.UnknownCommit expected){checks++;}
        check(unknown.opens==1 && unknown.commits==1 && unknown.closes==1);
        FakeSource broken=new FakeSource();broken.failRollback=true;
        try{Db.transaction(broken,c->{throw new SQLException("deadlock","40001",1213);});throw new AssertionError();}
        catch(SQLException expected){check(expected.getSuppressed().length==1);}
        check(broken.opens==1 && broken.closes==1);
        FakeSource ordinary=new FakeSource();
        try{Db.transaction(ordinary,c->{throw new SQLException("syntax","42000",1064);});throw new AssertionError();}
        catch(SQLException expected){checks++;}
        check(ordinary.opens==1 && ordinary.rollbacks==1);
        System.out.println("PASS "+checks+" Java-only checks; fake JDBC does not establish MySQL behavior");
    }
}

